CREATE OR REPLACE FUNCTION public.laundry_post_charge(_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v_org uuid:=current_org_id(); v_order record; v_folio uuid; v_line uuid; v_key text; v_system boolean:=public.neo_system_posting(); begin if not v_system and not (has_permission('laundry','edit') or has_permission('laundry','approve') or has_permission('laundry','complete') or has_permission('laundry','deliver') or has_permission('pms','folios.post_charge') or is_org_admin()) then raise exception 'Not permitted to post laundry charges'; end if; select * into v_order from guest_laundry_orders where id=_order and organization_id=v_org for update; if v_order is null then raise exception 'Unknown laundry order'; end if; if v_order.posting_status='posted' then return jsonb_build_object('ok',true,'already_posted',true,'folio_line_id',v_order.folio_line_id); end if; if coalesce(v_order.total,0)<=0 then return jsonb_build_object('ok',false,'reason','no_chargeable_items','detail','Count the laundry items and price them before posting the charge.'); end if; v_folio:=v_order.folio_id; if v_folio is null and v_order.reservation_id is not null then select id into v_folio from folios where organization_id=v_org and reservation_id=v_order.reservation_id and status='open' order by created_at limit 1; end if; if v_folio is null then return jsonb_build_object('ok',false,'reason','no_folio','detail','No open guest folio for this laundry order.'); end if; v_key:='laundry:'||_order::text; perform set_config('neo.system_posting','on',true); v_line:=public.folio_post_charge(v_folio,'laundry','Guest laundry '||coalesce(v_order.laundry_number,''),1,coalesce(v_order.total,0)-coalesce(v_order.tax_amount,0),coalesce(v_order.tax_amount,0),0,0,'laundry',_order,'laundry',v_key,null); update guest_laundry_orders set posting_status='posted',folio_id=v_folio,folio_line_id=v_line,posted_at=now() where id=_order; return jsonb_build_object('ok',true,'folio_line_id',v_line); end $function$
